import { useCallback, useEffect, useState, useRef, lazy, Suspense, type FormEvent, type ReactNode } from 'react';
import { LayoutDashboard, Building2, Users, Cctv, ScanFace, CalendarDays, UserRoundCheck, DoorOpen, ClipboardCheck, Bell, Wrench, Cpu, PlugZap, Zap, Megaphone, ShieldCheck, History, Search, Plus, ChevronDown, ArrowUpRight, ArrowRight, RefreshCw, Download, LogOut, Menu, X, Check, CircleHelp, Settings2, Shield, Layers, Cable, Activity, Video, KeyRound, Clock3, AlertTriangle, FileText } from 'lucide-react';
import { api, modules, roleNames, stateActions, stateNames, localDate, localInput, prettyTime, type Row, type Workspace, type User, type Field } from './model';
import { Brand, Badge, Empty, Modal, Panel, LinkButton, Steps, Table, cellValue, exportCsv } from './components';
import VideoAnalysis from './VideoAnalysis';
import DailyReport from './ProjectDailyReports';
import PhotoArchives from './PhotoArchives';
import Engineering from './MobileWorkspace';
import SiteDocumentLibrary from './SiteDocumentLibrary';
import { engineeringNavigationBlocked, notifyEngineeringNavigationBlocked } from './engineering-navigation-guard';
import AnalysisRegion, { FULL_FRAME } from './AnalysisRegion';
import { AlarmDock, SecurityPage, SecurityForm, SecurityEvidence, securityPages, securityForms } from './Security';
const TwinScreen = lazy(() => import('./Twin'));

const sections = [
  { title: '工作空间', items: [['dashboard', '运营工作台', LayoutDashboard], ['twin', '数字孪生大屏', Layers]] },
  { title: '工程管理', items: [['engineering', '项目与经营管理', Building2], ['site-library','全部项目资料',FileText], ['daily-report', '施工日报', ClipboardCheck], ['photo-archive', '施工影像资料', FileText]] },
  { title: '安全管理', items: [['video', '视频监控', Video], ['rules', 'AI 分析', ScanFace], ['security', '布控指挥台', Shield], ['alerts', '告警中心', Bell], ['workorders', '运维工单', Wrench]] },
  { title: '布控档案', items: [['portraits', '布控名单', Users], ['watches', '人像布控', ScanFace], ['captures', '人像抓拍', Cctv], ['fences', '围栏与围挡', Layers], ['detections', '围栏识别记录', History]] },
  { title: '智慧办公', items: [['visits', '访客管理', UserRoundCheck], ['bookings', '会议管理', CalendarDays], ['access', '通行记录', DoorOpen], ['attendance', '考勤记录', ClipboardCheck], ['energy', '能耗管理', Zap], ['announcements', '信息发布', Megaphone]] },
  { title: '基础管理', items: [['spaces', '场所空间', Building2], ['devices', '设备中心', Cctv], ['employees', '组织人员', Users], ['integrations', '接入中心', PlugZap], ['users', '账号权限', ShieldCheck], ['audit', '操作审计', History]] },
];
const pageTitle = (page: string) => sections.flatMap(s => s.items).find(i => i[0] === page)?.[1] as string || '运营工作台';
const adminPages = ['integrations', 'users', 'audit','site-library'];
const validPage = (page: string) => sections.some(s => s.items.some(i => i[0] === page)) ? page : 'dashboard';
const readRoute = (hash: string) => {
  const [name, query = ''] = hash.replace(/^#/, '').split('?');
  const page = validPage(name);
  return { page, device: ['rules', 'alerts', 'workorders'].includes(page) ? new URLSearchParams(query).get('device') || '' : '' };
};

export default function App() {
  const [status, setStatus] = useState<{ name: string; setupRequired: boolean } | null>(null);
  const [ws, setWs] = useState<Workspace | null>(null);
  const [page, setPage] = useState(readRoute(location.hash).page);
  const pageRef = useRef(page); pageRef.current = page;
  const [deviceFilter, setDeviceFilter] = useState(readRoute(location.hash).device);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [toast, setToast] = useState('');
  const [search, setSearch] = useState('');
  const [sidebar, setSidebar] = useState(false);
  const sidebarRef = useRef<HTMLElement>(null);
  const mainShellRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!sidebar || !window.matchMedia('(max-width: 760px)').matches) return;
    const previous = document.activeElement as HTMLElement | null;
    const overflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    const controls = () => Array.from(sidebarRef.current?.querySelectorAll<HTMLButtonElement>('button') || []).filter(button => button.getClientRects().length > 0);
    controls()[0]?.focus();
    const key = (event: KeyboardEvent) => {
      if (event.key === 'Escape') setSidebar(false);
      if (event.key === 'Tab') { const buttons = controls(); if (event.shiftKey && document.activeElement === buttons[0]) { event.preventDefault(); buttons.at(-1)?.focus(); } else if (!event.shiftKey && document.activeElement === buttons.at(-1)) { event.preventDefault(); buttons[0]?.focus(); } }
    };
    document.addEventListener('keydown', key);
    return () => { document.body.style.overflow = overflow; document.removeEventListener('keydown', key); previous?.focus(); };
  }, [sidebar]);
  const [expandedSections, setExpandedSections] = useState<string[]>(['工作空间', '安全管理']);
  useEffect(() => { const group = sections.find(section => section.items.some(([id]) => id === page)); if (group) setExpandedSections(current => current.includes(group.title) ? current : [...current, group.title]); }, [page]);
  const [form, setForm] = useState<{ type: string; row?: Row; initial?: Record<string, any> } | null>(null);
  const [selected, setSelected] = useState<Row | null>(null);
  const [profile, setProfile] = useState(false);
  const [lastSynced, setLastSynced] = useState(Date.now());
  const load = useCallback(async () => { const next = await api<Workspace>('/bootstrap'); setWs(next); setLastSynced(Date.now()); setSelected(current => current ? Object.values(next.records).flat().find(r => r.id === current.id) || null : null); }, []);
  const refresh = useCallback(async () => { try { await load(); setError(''); } catch (e: any) { if (e.status === 401) setWs(null); else setError(e.message); } }, [load]);
  useEffect(() => { api('/status').then(setStatus).then(() => load()).catch((e: any) => { if (e.status !== 401) setError(e.message); }).finally(() => setLoading(false)); }, [load]);
  useEffect(() => { const handle = (event: HashChangeEvent) => { const route = readRoute(location.hash); if (pageRef.current === 'engineering' && route.page !== 'engineering' && engineeringNavigationBlocked()) { const previous = new URL(event.oldURL).hash; history.replaceState(null, '', readRoute(previous).page === 'engineering' ? previous : '#engineering'); setSidebar(false); notifyEngineeringNavigationBlocked(); return; } setPage(route.page); setDeviceFilter(route.device); setSearch(''); setSidebar(false); }; window.addEventListener('hashchange', handle); return () => window.removeEventListener('hashchange', handle); }, []);
  useEffect(() => { window.scrollTo(0, 0); mainShellRef.current?.scrollTo(0, 0); }, [page]);
  useEffect(() => { if (!ws) return; const timer = setInterval(() => { if (!document.hidden) void refresh(); }, 30000); return () => clearInterval(timer); }, [!!ws, refresh]);
  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(''), 5000); return () => clearTimeout(timer); }, [toast]);
  const navigate = (next: string) => { const route = readRoute(next); if (pageRef.current === 'engineering' && route.page !== 'engineering' && engineeringNavigationBlocked()) { setSidebar(false); notifyEngineeringNavigationBlocked(); return; } location.hash = next; setPage(route.page); setDeviceFilter(route.device); setSearch(''); setSidebar(false); };
  const saved = async (message = '已保存') => { await load(); setToast(message); };
  const create = (type: string, initial?: Record<string, any>) => setForm({ type, initial });
  if (loading) return <div className="loading-screen"><Brand /><span className="spinner" /><p>正在连接工作空间</p></div>;
  if (!ws) return <Auth setup={!!status?.setupRequired} name={status?.name || '智慧工程'} error={error} done={async () => { await load(); setStatus(s => s ? { ...s, setupRequired: false } : s); }} />;
  const openAlerts = ws.records.alerts.filter(r => ['new', 'processing'].includes(r.state)).length;
  const isAdmin = ws.user.role === 'admin';
  const canWrite = ws.user.role !== 'viewer';
  const writable = (type: string) => canWrite && (!modules[type]?.adminOnly || isAdmin);
  const currentPage = adminPages.includes(page) && !isAdmin ? 'dashboard' : page;
  return <div className={`app-shell ${currentPage === 'twin' ? 'twin-mode' : ''}`}>
    {currentPage === 'twin' ? <Suspense fallback={<div className="loading-screen"><span className="spinner" /><p>正在加载数字孪生大屏</p></div>}><TwinScreen ws={ws} exit={() => navigate('dashboard')} select={setSelected} connectionError={error} lastSynced={lastSynced} /></Suspense> : <>
    {sidebar && <button className="sidebar-shade" aria-label="收起导航" onClick={() => setSidebar(false)} />}
    <aside ref={sidebarRef} className={`sidebar ${sidebar ? 'is-open' : ''}`}>
      <div className="sidebar-brand"><Brand light /><button className="mobile-close icon-button" aria-label="收起导航" onClick={() => setSidebar(false)}><X size={20} /></button></div>
      <div className="workspace-label"><span className="workspace-letter">{ws.organization.slice(0, 1)}</span><span>{ws.organization}<small>办公 · 安防 · 运维</small></span><Layers size={15} /></div>
      <nav aria-label="主导航">{sections.map((section, index) => {
        const expanded = expandedSections.includes(section.title);
        return <div className="nav-section" key={section.title}>
          <button className="nav-group-toggle" aria-expanded={expanded} aria-controls={`nav-group-${index}`} onClick={() => setExpandedSections(current => expanded ? current.filter(title => title !== section.title) : [...current, section.title])}>{section.title}<ChevronDown size={13} className={expanded ? 'expanded' : ''} /></button>
          <div id={`nav-group-${index}`} hidden={!expanded}>{section.items.filter(([id]) => !adminPages.includes(id as string) || isAdmin).map(([id, label, Icon]) => { const NavigationIcon = Icon as typeof LayoutDashboard; return <button key={id as string} onClick={() => navigate(id as string)} aria-current={currentPage === id ? 'page' : undefined} className={`nav-item ${currentPage === id ? 'active' : ''}`}><NavigationIcon size={18} strokeWidth={1.7} /><span>{label as string}</span>{id === 'alerts' && openAlerts > 0 && <b>{openAlerts}</b>}</button>; })}</div>
        </div>;
      })}</nav>
      <div className="sidebar-bottom"><span className={`connection-dot ${error ? 'disconnected' : ''}`} /><span>{error ? '工作空间连接异常' : '工作空间已连接'}<small>{error ? '请重试获取最新状态' : '业务数据自动保存'}</small></span><Shield size={17} /></div>
    </aside>
    <div ref={mainShellRef} className="main-shell">
      <header className="topbar"><div className="breadcrumb"><button className="icon-button mobile-menu" aria-label="展开导航" onClick={() => setSidebar(true)}><Menu size={21} /></button><span>管理平台</span><span className="slash">/</span><strong>{pageTitle(currentPage)}</strong></div><div className="topbar-actions">{!['engineering','daily-report','photo-archive'].includes(currentPage) && <div className="global-search"><Search size={16} /><input aria-label="搜索当前业务" placeholder={currentPage === 'dashboard' ? '搜索业务记录…' : '搜索当前业务…'} value={search} onChange={e => setSearch(e.target.value)} /><kbd>检索</kbd></div>}<button className="icon-button notification-button" onClick={() => navigate('alerts')} aria-label={`告警中心，${openAlerts}条待处理`}><Bell size={19} />{openAlerts > 0 && <i />}</button><span className="topbar-divider" /><button className="profile-button" onClick={() => setProfile(true)}><span className="avatar">{ws.user.name.slice(-2)}</span><span>{ws.user.name}<small>{roleNames[ws.user.role]}</small></span><ChevronDown size={13} /></button></div></header>
      <main>
        {error && <div className="error-banner" role="alert">{error}<button className="text-button" onClick={() => void refresh()}>重试</button></div>}
        {currentPage === 'engineering' ? <Engineering key={ws.user.id} user={ws.user}/> : currentPage === 'site-library' ? <SiteDocumentLibrary admin onOpenRecord={(projectId,recordId)=>{navigate('engineering?view=projects&module=documents&project='+encodeURIComponent(projectId)+'&item='+encodeURIComponent(recordId));}}/> : currentPage === 'photo-archive' ? <DailyReport kind="photo" key={ws.user.id} user={ws.user} /> : currentPage === 'daily-report' ? <DailyReport key={ws.user.id} user={ws.user} /> : currentPage === 'dashboard' ? <Dashboard ws={ws} navigate={navigate} search={search} select={setSelected} create={create} canWrite={canWrite} /> : securityPages.includes(currentPage) ? <SecurityPage ws={ws} page={currentPage} search={search} navigate={navigate} create={create} select={setSelected} refresh={refresh} /> : modules[currentPage] ? <ResourcePage ws={ws} type={currentPage} search={search} deviceFilter={deviceFilter} navigate={navigate} create={() => create(currentPage, deviceFilter ? { deviceId: deviceFilter } : undefined)} select={setSelected} canWrite={writable(currentPage)} refresh={refresh} /> : currentPage === 'integrations' ? <IntegrationPage ws={ws} saved={saved} /> : currentPage === 'users' ? <UserPage user={ws.user} saved={saved} /> : currentPage === 'audit' ? <AuditPage search={search} /> : <VideoAnalysis ws={ws} navigate={navigate} create={create} changed={refresh} />}
        <footer className="page-footer"><span>智慧工程 · 统一工作空间</span><span>数据按当前单位管理 <span className="footer-dot">·</span> v{ws.version}</span></footer>
      </main>
    </div>
    </>}
    {form && (securityForms.includes(form.type) ? <SecurityForm ws={ws} type={form.type} row={form.row} onClose={() => setForm(null)} saved={async () => { await saved(); setForm(null); }} /> : <RecordForm ws={ws} type={form.type} row={form.row} initial={form.initial} onClose={() => setForm(null)} saved={async () => { await saved(); setForm(null); }} />)}
    {selected && !form && <RecordDetail key={selected.id} ws={ws} row={selected} canWrite={writable(selected.type)} onClose={() => setSelected(null)} saved={saved} onSelect={setSelected} edit={() => setForm({ type: selected.type, row: selected })} createOrder={() => { setForm({ type: 'workorders', initial: { name: `处理：${selected.data.name}`, alertId: selected.id, deviceId: selected.data.deviceId, priority: selected.data.priority, description: selected.data.description, assigneeId: selected.data.assigneeId } }); setSelected(null); }} />}
    {profile && <Profile user={ws.user} onClose={() => setProfile(false)} saved={saved} logout={async () => { if (pageRef.current === 'engineering' && engineeringNavigationBlocked(false)) { setProfile(false); notifyEngineeringNavigationBlocked(); return; } await api('/logout', 'POST', {}); setProfile(false); setWs(null); }} />}
    <AlarmDock ws={ws} refresh={refresh} select={setSelected} navigate={navigate} />
    {toast && <div className="toast" role="status"><Check size={17} />{toast}</div>}
  </div>;
}

function Auth({ setup, name, error: externalError, done }: { setup: boolean; name: string; error: string; done: () => Promise<void> }) {
  const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  const submit = async (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const values = Object.fromEntries(new FormData(e.currentTarget)); setBusy(true); setError(''); try { if (setup) { if (values.password !== values.confirm) throw new Error('两次密码输入不一致'); delete values.confirm; } await api(setup ? '/setup' : '/login', 'POST', values); await done(); } catch (e: any) { setError(e.message); } finally { setBusy(false); } };
  return <div className="auth-screen"><section className="auth-story"><Brand light /><div className="auth-story-content"><h1>让管理更有序，<br />让安全看得见。</h1><p>智慧办公与 AI 安防的统一工作平台</p><div className="auth-capabilities"><div><Video size={23} /><span><strong>视频与智能分析</strong><small>摄像头接入 · 场景规则 · 识别证据</small></span></div><div><ShieldCheck size={23} /><span><strong>布控与事件处置</strong><small>人像布控 · 区域防护 · 独立告警</small></span></div><div><Building2 size={23} /><span><strong>办公与运维协同</strong><small>人员空间 · 访客会议 · 维护工单</small></span></div></div></div><div className="auth-story-bottom"><span>智慧办公</span><i /><span>AI安防</span><i /><span>统一运维</span></div></section><section className="auth-form-side"><div className="auth-form-wrap"><span className="auth-icon"><Layers size={24} /></span><h2>{setup ? '开始协同管理' : `登录${name}`}</h2><p>{setup ? '设置单位名称和首个管理员，开始录入真实业务。' : '使用你的平台账号继续工作。'}</p><form onSubmit={submit}>{setup && <><label>单位 / 项目名称<input name="organization" placeholder="例如：园区运营管理中心" required maxLength={100} /></label><label>管理员姓名<input name="name" placeholder="输入你的姓名" required maxLength={60} autoComplete="name" /></label></>}<label>账号<input name="username" placeholder="3–40 位字母、数字或下划线" required pattern="[a-zA-Z0-9_.\-]{3,40}" autoComplete="username" /></label><label>密码<input name="password" type="password" placeholder={setup ? '至少 6 位' : '输入密码'} required minLength={setup ? 6 : 1} maxLength={128} autoComplete={setup ? 'new-password' : 'current-password'} /></label>{setup && <label>确认密码<input name="confirm" type="password" placeholder="再次输入密码" required minLength={6} autoComplete="new-password" /></label>}{(error || externalError) && <div className="form-error" role="alert">{error || externalError}</div>}<button className="button primary full" disabled={busy}>{busy ? '正在处理…' : setup ? '创建工作空间' : '进入工作空间'}<ArrowRight size={17} /></button></form><div className="auth-footnote"><ShieldCheck size={15} />{setup ? '没有预设密码，由你保管管理员账号。' : '账号权限由本单位管理员分配。'}</div></div><small className="auth-copyright">智慧工程 · SMART WORKSPACE</small></section></div>;
}

function PageHeading({ title, description, children }: { eyebrow: string; title: string; description: string; children?: ReactNode }) { return <div className="page-heading"><div><h1>{title}</h1><p>{description}</p></div><div className="heading-actions">{children}</div></div>; }

function Dashboard({ ws, navigate, search, select, create, canWrite }: { ws: Workspace; navigate: (p: string) => void; search: string; select: (r: Row) => void; create: (type: string) => void; canWrite: boolean }) {
  const r = ws.records; const today = localDate();
  const pending = r.alerts.filter(a => ['new', 'processing'].includes(a.state));
  const orders = r.workorders.filter(o => ['open', 'in_progress'].includes(o.state));
  const meetings = r.bookings.filter(b => localDate(Date.parse(b.data.startAt)) === today && b.state === 'reserved').sort((a, b) => a.data.startAt.localeCompare(b.data.startAt));
  const guests = r.visits.filter(v => v.state === 'requested');
  const connected = r.devices.filter(d => d.state === 'online');
  const connectedCameras = connected.filter(device => device.data.kind === 'camera');
  const steps = [{ title: '建立空间目录', detail: `${r.spaces.length} 个场所`, done: !!r.spaces.length, page: 'spaces' }, { title: '登记现场设备', detail: `${r.devices.length} 台设备`, done: !!r.devices.length, page: 'devices' }, { title: '连接摄像头', detail: connectedCameras.length ? `${connectedCameras.length} 台已上报在线` : '配置视频源与连接', done: !!connectedCameras.length, page: 'video' }, { title: '配置分析规则', detail: `${r.rules.filter(rule => rule.state === 'active').length} 条已启用`, done: r.rules.some(rule => rule.state === 'active'), page: 'rules' }];
  const dates = Array.from({ length: 7 }, (_, i) => localDate(Date.now() - (6 - i) * 86400000));
  const daily = dates.map(date => r.alerts.filter(a => localDate(Date.parse(a.data.occurredAt)) === date).length); const max = Math.max(1, ...daily);
  const filtered = Object.values(r).flat().filter(row => JSON.stringify(row.data).toLowerCase().includes(search.toLowerCase()));
  const latest = [...r.alerts].sort((a, b) => b.data.occurredAt.localeCompare(a.data.occurredAt)).slice(0, 5);
  const duties = [{ label: '告警待处置', detail: '确认事件并跟进处理', count: pending.length, page: 'alerts', icon: Bell }, { label: '工单待完成', detail: '跟进现场维护与修复', count: orders.length, page: 'workorders', icon: Wrench }, { label: '设备待确认在线', detail: '核对连接和状态上报', count: r.devices.length - connected.length, page: 'devices', icon: Cctv }, { label: '访客待审批', detail: '确认来访预约信息', count: guests.length, page: 'visits', icon: UserRoundCheck }];
  return <><PageHeading eyebrow="" title="运营工作台" description={new Date().toLocaleDateString('zh-CN', { timeZone: 'Asia/Shanghai', year: 'numeric', month: 'long', day: 'numeric', weekday: 'long' })}><button className="button secondary" onClick={() => navigate('twin')}><Layers size={16} />数字孪生大屏</button><button className="button primary" onClick={() => navigate('video')}><Video size={17} />进入视频监控</button></PageHeading>
    {search ? <Panel title={`搜索结果 · ${filtered.length}`} meta={`关键词：${search}`}><div className="search-results">{filtered.length ? filtered.map(row => <button key={row.id} onClick={() => select(row)}><span className="result-icon"><Search size={18} /></span><span><strong>{row.data.name || modules[row.type]?.singular || '业务记录'}</strong><small>{modules[row.type]?.name || '业务记录'} · {prettyTime(row.updated_at)}</small></span><ArrowUpRight size={18} /></button>) : <Empty title="没有找到记录" description="尝试姓名、设备编号或业务名称。" />}</div></Panel> : <>
      <div className="metrics-grid">{[{ label: '待处置告警', value: pending.length, text: '待确认与处理中', page: 'alerts', icon: Bell }, { label: '待办工单', value: orders.length, text: '维护任务与修复跟进', page: 'workorders', icon: Wrench }, { label: '在线设备', value: `${connected.length} / ${r.devices.length}`, text: '已上报在线 / 登记总数', page: 'devices', icon: Cctv }, { label: '今日会议', value: meetings.length, text: '已确认的会议安排', page: 'bookings', icon: CalendarDays }].map(item => <button className="metric-card" key={item.label} onClick={() => navigate(item.page)}><span className="metric-label">{item.label}<item.icon size={18} /></span><strong>{item.value}</strong><span className="metric-foot">{item.text}<ArrowUpRight size={14} /></span></button>)}</div>
      {canWrite && steps.some(step => !step.done) && <Panel title="接入准备" meta="完成配置，让现场数据进入工作台" className="onboarding-panel" action={<span className="completion-count">{steps.filter(step => step.done).length}<small> / 4</small></span>}><Steps steps={steps} navigate={navigate} /></Panel>}
      <div className="dashboard-grid"><div className="dashboard-primary">
        <Panel title="近期告警" meta="事件发生后可进入详情核验与处置" action={<LinkButton onClick={() => navigate('alerts')}>全部告警</LinkButton>}>{latest.length ? <div className="dashboard-alert-list">{latest.map(alert => <button key={alert.id} onClick={() => select(alert)}><span><strong>{alert.data.name}</strong><small>{cellValue(ws, 'alerts', alert, 'deviceId')} · {prettyTime(alert.data.occurredAt, true)}</small></span><Badge state={alert.data.priority} /><Badge state={alert.state} /><ArrowUpRight size={15} /></button>)}</div> : <div className="dashboard-alarm-empty"><span className="empty-icon"><ShieldCheck size={29} strokeWidth={1.4} /></span><h3>暂无告警记录</h3><p>接入摄像头并启用规则后，识别事件将在这里汇总。</p><button className="text-button" onClick={() => navigate('video')}>前往视频监控<ArrowRight size={15} /></button></div>}</Panel>
        <Panel title="事件趋势" meta="近 7 天实际告警数量" action={<span className="trend-total">{daily.reduce((sum, n) => sum + n, 0)}<small> 条事件</small></span>}><div className="trend-chart" role="img" aria-label={dates.map((date, i) => `${date}：${daily[i]} 条告警`).join('；')}><div className="chart-grid-lines" aria-hidden="true"><span /><span /><span /></div>{dates.map((date, i) => <div className="chart-column" key={date}><span className="chart-value">{daily[i]}</span><div className="chart-bar-track"><i style={{ height: `${daily[i] / max * 100}%` }} /></div><small>{date.slice(5).replace('-', '/')}</small></div>)}</div></Panel>
      </div><div className="dashboard-secondary">
        <Panel title="值守待办" meta="按当前业务记录汇总"><div className="duty-list">{duties.map(duty => <button key={duty.page} className={duty.count ? 'needs-attention' : ''} onClick={() => navigate(duty.page)}><duty.icon size={18} /><span><strong>{duty.label}</strong><small>{duty.detail}</small></span><b>{duty.count}</b><ArrowUpRight size={14} /></button>)}</div></Panel>
        <Panel title="今日会议" action={<LinkButton onClick={() => navigate('bookings')}>全部</LinkButton>}>{meetings.length ? <div className="agenda-list">{meetings.slice(0, 4).map(meeting => <button key={meeting.id} onClick={() => select(meeting)}><span className="agenda-time">{prettyTime(meeting.data.startAt, true).split(' ').at(-1)}</span><span><strong>{meeting.data.name}</strong><small>{cellValue(ws, 'bookings', meeting, 'spaceId')}</small></span></button>)}</div> : <div className="small-empty"><CalendarDays size={24} /><strong>今天暂无会议安排</strong>{canWrite && <button className="text-button" onClick={() => create('bookings')}>预约会议<Plus size={14} /></button>}</div>}</Panel>
        <Panel title="常用业务"><div className="quick-links">{[['visits', '访客预约', UserRoundCheck], ['devices', '设备管理', Cctv], ['captures', '人像抓拍', ScanFace], ['fences', '电子围栏', Layers]].map(([id, label, Icon]) => { const I = Icon as typeof Cctv; return <button key={id as string} onClick={() => navigate(id as string)}><span><I size={19} strokeWidth={1.7} /></span>{label as string}<ArrowUpRight size={14} /></button>; })}</div></Panel>
      </div></div>
    </>}
  </>;
}

function ResourcePage({ ws, type, search, create, select, canWrite, refresh, deviceFilter, navigate }: { ws: Workspace; type: string; search: string; create: () => void; select: (r: Row) => void; canWrite: boolean; refresh: () => Promise<void>; deviceFilter: string; navigate: (page: string) => void }) {
  const [filter, setFilter] = useState('all'); const [view, setView] = useState('records'); const [date, setDate] = useState(localDate()); const [summary, setSummary] = useState<any[]>([]); const [summaryError, setSummaryError] = useState('');
  useEffect(() => { setFilter('all'); setView('records'); }, [type, deviceFilter]);
  useEffect(() => { if (type !== 'attendance' || view !== 'summary') return; let disposed = false; api(`/attendance-summary?date=${date}`).then(data => { if (!disposed) { setSummary(data); setSummaryError(''); } }).catch(e => { if (!disposed) setSummaryError(e.message); }); return () => { disposed = true; }; }, [type, view, date, ws]);
  const config = modules[type]; const scoped = ['rules', 'alerts', 'workorders'].includes(type);
  const all = ws.records[type].filter(r => !scoped || !deviceFilter || r.data.deviceId === deviceFilter); const states = [...new Set(all.map(r => r.state))];
  const rows = all.filter(r => (filter === 'all' || r.state === filter) && JSON.stringify(r.data).toLowerCase().includes(search.toLowerCase()));
  const cameras = ws.records.devices.filter(d => d.data.kind === 'camera'); const rooms = ws.records.spaces.filter(s => s.data.kind === 'meeting_room');
  return <><PageHeading eyebrow={`WORKSPACE / ${config.name}`} title={config.name} description={config.description}><button className="button secondary" onClick={() => exportCsv(ws, type, rows)} disabled={!rows.length}><Download size={16} />导出记录</button>{canWrite && <button className="button primary" onClick={create}><Plus size={17} />{config.create || `添加${config.singular}`}</button>}</PageHeading>
    {type === 'bookings' && rooms.length > 0 && <div className="room-grid">{rooms.map(room => { const current = all.find(r => r.data.spaceId === room.id && r.state === 'reserved' && Date.parse(r.data.startAt) <= Date.now() && Date.parse(r.data.endAt) > Date.now()); return <div className="room-card" key={room.id}><span className="room-icon"><Building2 size={23} /></span><div><strong>{room.data.name}</strong><small>{room.data.capacity ? `${room.data.capacity} 人` : '容量未设置'} · {room.data.code}</small></div><Badge state={current ? 'processing' : 'active'}>{current ? '使用中' : '当前空闲'}</Badge></div>; })}</div>}
    {type === 'rules' && <><div className="context-banner"><Cpu size={21} /><div><strong>算法规则与推理服务分别管理</strong><p>共 {ws.algorithms.length} 类场景，{ws.algorithms.filter(a => a.status === 'installed').length} 类具备本机实现。先在视频监控配置并启动视频源，再启用规则；未提供模型的项目无法启用。</p></div></div><div className="algorithm-groups">{['人员分析', '行为分析', '场景分析', '视频诊断'].map(group => <section key={group}><span className="algorithm-group-icon"><ScanFace size={20} /></span><h3>{group}</h3><p>{ws.algorithms.filter(a => a.group === group).map(a => a.name).join(' · ')}</p><span className="pending-label">{ws.algorithms.filter(a => a.group === group && a.status === 'installed').length} 类可配置本机分析 · 现场效果待联调</span></section>)}</div></>}
    {['access', 'attendance', 'announcements', 'energy'].includes(type) && <div className="notice-line"><CircleHelp size={16} />{({ access: '通行记录与真实开门指令分别验收；人工补录不会操作现场设备。', attendance: '每日汇总按北京时间配对上下班记录；排班、迟到早退与薪资核算尚未启用。', announcements: '内容保存为草稿，尚未向现场信息屏下发。', energy: '本页展示累计表计读数，不将不同单位或不同设备的读数直接相加。' } as Record<string, string>)[type]}</div>}
    <Panel title={type === 'rules' ? '规则配置' : `${config.name}记录`} meta={`${all.length} 条`} action={<button className="icon-button" aria-label="刷新列表" onClick={() => void refresh()}><RefreshCw size={16} /></button>}>
      {scoped && <div className="device-scope-filter"><label>按设备查看<select value={deviceFilter} onChange={e => navigate(`${type}${e.target.value ? '?device='+encodeURIComponent(e.target.value) : ''}`)}><option value="">全部设备</option>{deviceFilter && !ws.records.devices.some(d => d.id === deviceFilter) && <option value={deviceFilter}>设备记录已不可用</option>}{ws.records.devices.map(d => <option key={d.id} value={d.id}>{d.data.name} · {d.data.code}</option>)}</select></label>{deviceFilter && <button className="text-button" onClick={() => navigate(type)}>清除设备筛选</button>}</div>}
      <div className="list-toolbar"><div className="filter-tabs"><button className={filter === 'all' ? 'selected' : ''} onClick={() => setFilter('all')}>全部 <span>{all.length}</span></button>{states.map(state => <button className={filter === state ? 'selected' : ''} key={state} onClick={() => setFilter(state)}>{stateNames[state] || state}<span>{all.filter(r => r.state === state).length}</span></button>)}</div>{type === 'attendance' && <div className="segmented"><button className={view === 'records' ? 'active' : ''} onClick={() => setView('records')}>原始记录</button><button className={view === 'summary' ? 'active' : ''} onClick={() => setView('summary')}>每日汇总</button></div>}</div>
      {view === 'summary' && type === 'attendance' ? <div className="attendance-summary"><label className="date-filter">汇总日期<input aria-label="考勤汇总日期" type="date" value={date} onChange={e => setDate(e.target.value)} /></label>{summaryError && <div className="form-error">{summaryError}</div>}<div className="table-scroll"><table><thead><tr><th>姓名</th><th>部门</th><th>首次上班</th><th>末次下班</th><th>记录数</th><th>记录完整性</th></tr></thead><tbody>{summary.filter(s => `${s.name}${s.department}`.includes(search)).map(s => <tr key={s.id}><td>{s.name}</td><td>{s.department}</td><td>{prettyTime(s.firstIn, true)}</td><td>{prettyTime(s.lastOut, true)}</td><td>{s.count}</td><td><Badge state={s.state} /></td></tr>)}</tbody></table></div>{!summary.length && <Empty title="暂无人员汇总" description="先建立人员档案，再接入或补录打卡记录。" />}</div> : rows.length ? <Table ws={ws} type={type} rows={rows} onSelect={select} /> : <Empty title={all.length ? '没有符合条件的记录' : `尚无${config.singular}`} description={all.length ? '调整筛选条件或搜索关键词。' : config.empty} action={canWrite && !all.length ? <button className="button secondary" onClick={create}><Plus size={16} />{config.create || `添加${config.singular}`}</button> : undefined} />}
      <div className="table-foot"><span>共 {rows.length} 条符合条件的记录</span><span>数据来自本单位登记与接入服务</span></div>
    </Panel>
  </>;
}

function RecordForm({ ws, type, row, initial, onClose, saved }: { ws: Workspace; type: string; row?: Row; initial?: Record<string, any>; onClose: () => void; saved: () => Promise<void> }) {
  const config = modules[type];
  const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  const [cameraId, setCameraId] = useState(row?.data.deviceId || initial?.deviceId || '');
  const [algorithm, setAlgorithm] = useState(row?.data.algorithm || initial?.algorithm || '');
  const [roi, setRoi] = useState(row?.data.roi || initial?.roi || FULL_FRAME);
  const options = (field: Field) => {
    if (field.ref === 'algorithms') return ws.algorithms.map(a => [a.id, `${a.name} · ${a.status === 'installed' ? '模型已安装' : '待补模型'}`]);
    let rows = ws.records[field.ref || ''] || [];
    if (field.ref === 'rooms') rows = ws.records.spaces.filter(s => s.data.kind === 'meeting_room');
    if (field.ref === 'cameras') rows = ws.records.devices.filter(d => d.data.kind === 'camera');
    if (field.ref === 'meters') rows = ws.records.devices.filter(d => d.data.kind === 'meter');
    if (field.ref === 'doors') rows = ws.records.devices.filter(d => ['access', 'gate', 'lift'].includes(d.data.kind));
    return rows.filter(r => (field.key !== 'parentId' || r.id !== row?.id) && (r.type !== 'employees' || r.state === 'active')).map(r => [r.id, r.data.name]);
  };
  const submit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); setError(''); setBusy(true); const fd = new FormData(event.currentTarget); const data: Record<string, any> = {};
    try { for (const field of config.fields) { const value = String(fd.get(field.key) || '').trim(); data[field.key] = field.kind === 'number' ? Number(value || field.default || 0) : field.kind === 'datetime-local' && value ? new Date(value).toISOString() : value; }
      await api(`/records/${type}${row ? `/${row.id}` : ''}`, row ? 'PATCH' : 'POST', row ? { version: row.version, data } : data); await saved();
    } catch (e: any) { setError(e.message); } finally { setBusy(false); }
  };
  return <Modal title={`${row ? '编辑' : '新建'}${config.singular}`} subtitle="保存后将写入本单位业务记录" onClose={onClose} wide><form onSubmit={submit}><div className="form-grid">{config.fields.map(field => {
    let value = row?.data[field.key] ?? initial?.[field.key] ?? field.default ?? '';
    if (type === 'rules' && !row && initial?.[field.key] === undefined && algorithm === 'smoking') {
      if (field.key === 'confidence') value = .5;
      if (field.key === 'dwellSeconds') value = 0;
    }
    if (field.kind === 'datetime-local') value = value ? localInput(value) : field.required ? localInput(new Date(Date.now() + (field.key === 'endAt' ? 3600000 : 0)).toISOString()) : '';
    const choices = field.ref ? options(field) : field.options;
    if (type === 'rules' && field.key === 'roi') return <AnalysisRegion key={cameraId} deviceId={cameraId} value={roi} onChange={setRoi} diagnostic={['blur', 'night', 'occlusion'].includes(algorithm)} />;
    return <label className={field.kind === 'textarea' ? 'span-two' : ''} key={field.key}>{field.label}{field.required && <em>*</em>}{choices ? <select name={field.key} defaultValue={value} required={field.required} onChange={e => { if (type === 'rules' && field.key === 'deviceId') { setCameraId(e.target.value); setRoi(FULL_FRAME); } if (type === 'rules' && field.key === 'algorithm') setAlgorithm(e.target.value); }}><option value="">{choices.length ? '请选择' : '请先添加关联记录'}</option>{choices.map(([id, label]) => <option key={id} value={id}>{label}</option>)}</select> : field.kind === 'textarea' ? <textarea name={field.key} defaultValue={value} required={field.required} rows={3} maxLength={field.key === 'content' ? 5000 : 2000} /> : <input key={type === 'rules' && !row && ['confidence', 'dwellSeconds'].includes(field.key) ? `${field.key}:${algorithm}` : field.key} name={field.key} type={field.kind || 'text'} defaultValue={value} required={field.required} min={field.min} max={field.max} step={field.step} maxLength={field.kind === 'number' ? undefined : 240} />}{field.hint && <small>{field.hint}</small>}{type === 'rules' && field.key === 'algorithm' && <small>{ws.algorithms.find(a => a.id === algorithm)?.limitation}{algorithm === 'smoking' && ' 建议先用分值 0.5、持续时长 0 秒联调，再按现场误报情况调整。'}</small>}</label>;
  })}</div>{error && <div className="form-error" role="alert">{error}</div>}<div className="modal-footer"><button type="button" className="button secondary" onClick={onClose}>取消</button><button className="button primary" disabled={busy}>{busy ? '正在保存…' : '保存记录'}</button></div></form></Modal>;
}

function RecordDetail({ ws, row, canWrite, onClose, saved, edit, createOrder, onSelect }: { onSelect: (row: Row) => void; ws: Workspace; row: Row; canWrite: boolean; onClose: () => void; saved: (s?: string) => Promise<void>; edit: () => void; createOrder: () => void }) {
  const [note, setNote] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false); const [deleteConfirm, setDeleteConfirm] = useState(false);
  const config = modules[row.type]; const actions = stateActions[row.type]?.[row.state] || [];
  const relatedOrders = row.type === 'alerts' ? ws.records.workorders.filter(order => order.data.alertId === row.id) : [];
  const openOrder = relatedOrders.find(order => !['completed', 'cancelled'].includes(order.state));
  const sourceAlert = row.type === 'workorders' ? ws.records.alerts.find(alert => alert.id === row.data.alertId) : undefined;
  const editable = !['access', 'attendance', 'energy', 'captures', 'detections'].includes(row.type) && !row.data.automatic && !(securityForms.includes(row.type) && row.state === 'armed') && !(row.type === 'visits' && !['requested', 'approved'].includes(row.state)) && !(row.type === 'bookings' && row.state !== 'reserved');
  const transition = async (state: string) => { setBusy(true); setError(''); try { await api(`/records/${row.type}/${row.id}/transition`, 'POST', { version: row.version, state, note }); await saved('状态已更新'); setNote(''); } catch (e: any) { setError(e.message); } finally { setBusy(false); } };
  const remove = async () => { setBusy(true); try { await api(`/records/${row.type}/${row.id}`, 'DELETE', { version: row.version }); await saved('记录已删除'); onClose(); } catch (e: any) { setError(e.message); } finally { setBusy(false); } };
  return <Modal title={row.data.name || config.singular} subtitle={`${config.name} · 创建于 ${prettyTime(row.created_at)}`} onClose={onClose} wide><div className="detail-top"><Badge state={row.state} />{row.data.source && <span className="source-label">{cellValue(ws, row.type, row, 'source')}</span>}{canWrite && editable && <button className="button secondary small" onClick={edit}><Settings2 size={14} />编辑</button>}</div>{(securityPages.includes(row.type) || row.data.automatic) && <SecurityEvidence row={row} ws={ws} select={onSelect} />}<dl className="detail-grid">{config.fields.map(f => <div key={f.key} className={f.kind === 'textarea' ? 'span-two' : ''}><dt>{f.label}</dt><dd>{cellValue(ws, row.type, row, f.key)}</dd></div>)}</dl>{sourceAlert && <div className="security-related"><button className="button secondary small" disabled={busy} onClick={() => onSelect(sourceAlert)}><Bell size={14} />查看来源告警与证据</button></div>}{relatedOrders.length > 0 && <div className="security-related">{relatedOrders.map(order => <button className="button secondary small" key={order.id} disabled={busy} onClick={() => onSelect(order)}><Wrench size={14} />{order.data.name} · {stateNames[order.state] || order.state}</button>)}</div>}{row.type === 'devices' && <div className="notice-line"><Cable size={16} />{row.data.lastSeen ? `最近上报：${prettyTime(row.data.lastSeen)}；来源：${row.data.reportSource}` : '尚未收到设备状态。登记设备不会自动连接现场设备。'}</div>}{row.data.history?.length > 0 && <section className="detail-history"><h3>流转记录</h3>{row.data.history.map((h: any, i: number) => <div key={i}><span className="timeline-dot" /><strong>{stateNames[h.state] || h.state}</strong><small>{h.actor} · {prettyTime(h.at)}</small>{h.note && <p>{h.note}</p>}</div>)}</section>}{canWrite && actions.length > 0 && <label className="detail-note">处理说明<textarea rows={2} value={note} onChange={e => setNote(e.target.value)} placeholder="关闭、忽略、取消或完成时必填" maxLength={2000} /></label>}{error && <div className="form-error" role="alert">{error}</div>}<div className="modal-footer detail-actions">{ws.user.role === 'admin' && ['spaces', 'employees', 'devices', 'rules', 'announcements'].includes(row.type) && <button className="button danger-ghost" disabled={busy} onClick={() => deleteConfirm ? void remove() : setDeleteConfirm(true)}>{deleteConfirm ? '确认删除此记录' : '删除'}</button>}{canWrite && row.type === 'alerts' && !openOrder && <button className="button secondary" disabled={busy} onClick={createOrder}>转为运维工单</button>}{canWrite && actions.map(([state, label], i) => <button key={state} disabled={busy} className={`button ${i === 0 ? 'primary' : 'secondary'}`} onClick={() => void transition(state)}>{label}</button>)}<button className="button secondary" onClick={onClose}>关闭</button></div></Modal>;
}

function IntegrationPage({ ws, saved }: { ws: Workspace; saved: (s?: string) => Promise<void> }) {
  const [rows, setRows] = useState<any[]>([]); const [open, setOpen] = useState(false); const [error, setError] = useState(''); const [token, setToken] = useState(''); const [busy, setBusy] = useState(false); const [revoke, setRevoke] = useState<string | null>(null);
  const load = useCallback(() => api('/integrations').then(setRows).catch(e => setError(e.message)), []); useEffect(() => { void load(); }, [load]);
  const submit = async (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const fd = new FormData(e.currentTarget); setBusy(true); setError(''); try { const result = await api('/integrations', 'POST', { name: fd.get('name'), kind: fd.get('kind'), deviceIds: fd.getAll('deviceIds') }); setToken(result.token); setOpen(false); await load(); await saved('接入凭据已建立'); } catch (e: any) { setError(e.message); } finally { setBusy(false); } };
  return <><PageHeading eyebrow="PLATFORM / 服务连接" title="接入中心" description="为不同服务分配独立凭据，限定事件类型与设备范围。"><button className="button primary" onClick={() => { setOpen(true); setError(''); }} disabled={!ws.records.devices.length}><Plus size={17} />建立服务接入</button></PageHeading><div className="context-banner"><Cable size={22} /><div><strong>连接真实设备与算法服务</strong><p>先登记设备，再创建对应服务的接入凭据。接收状态与事件不等于已完成视频解码或模型推理。</p></div></div><div className="integration-types">{[['ai', 'AI事件服务', '接收外部引擎识别结果', ScanFace], ['access', '门禁与考勤', '接收通行及打卡记录', DoorOpen], ['device', '设备状态', '接收在线、离线心跳', Cctv], ['energy', '能耗采集', '接收计量设备读数', Zap]].map(([id, label, desc, Icon]) => { const I = Icon as typeof Cpu; return <div key={id as string}><I size={24} /><h3>{label as string}</h3><p>{desc as string}</p><small>{rows.filter(r => r.kind === id && !r.revoked).length} 个有效接入</small></div>; })}</div>{error && !open && <div className="form-error" role="alert">{error}</div>}<Panel title="已配置服务" meta={`${rows.length} 个`}>{rows.length ? <div className="table-scroll"><table><thead><tr><th>服务名称</th><th>类型</th><th>授权设备</th><th>接收事件</th><th>最近通信</th><th>状态</th><th>操作</th></tr></thead><tbody>{rows.map(row => <tr key={row.id}><td><strong>{row.name}</strong></td><td>{{ ai: 'AI事件', access: '门禁考勤', device: '设备心跳', energy: '能耗' }[row.kind as string]}</td><td>{row.device_ids.length} 台</td><td>{row.received}</td><td>{prettyTime(row.last_seen, true)}</td><td><Badge state={row.revoked ? 'inactive' : row.last_seen ? 'active' : 'unverified'}>{row.revoked ? '已撤销' : row.last_seen ? '已收到数据' : '等待首条数据'}</Badge></td><td>{!row.revoked && <button className="text-button danger-text" onClick={() => setRevoke(row.id)}>撤销</button>}</td></tr>)}</tbody></table></div> : <Empty title="现场服务尚未连接" description={ws.records.devices.length ? '创建独立凭据，并由对应设备网关或算法服务推送数据。' : '先在设备中心添加需要接入的设备。'} />}</Panel><Panel title="接入说明" className="integration-guide"><p>接入采用独立 Bearer 密钥，并校验授权设备和事件编号。同一事件重复提交不会重复入库。</p><div><code>POST /api/ingest/telemetry</code><span>设备状态</span></div><div><code>POST /api/ingest/alerts</code><span>AI事件</span></div><div><code>POST /api/ingest/access</code><span>通行记录</span></div><div><code>POST /api/ingest/attendance</code><span>打卡记录</span></div><div><code>POST /api/ingest/energy</code><span>能耗读数</span></div><p>厂商协议网关、视频服务和算法引擎需要单独部署与联调。平台当前不会发出设备控制指令。</p></Panel>
    {open && <Modal title="建立服务接入" subtitle="密钥仅对选择的事件类型和设备生效" onClose={() => setOpen(false)}><form onSubmit={submit}><div className="form-stack"><label>服务名称<input name="name" required maxLength={120} placeholder="例如：一号楼设备状态网关" /></label><label>服务类型<select name="kind"><option value="device">设备状态</option><option value="ai">AI事件</option><option value="access">通行与考勤</option><option value="energy">能耗采集</option></select></label><fieldset><legend>授权设备（至少选择一台）</legend><div className="checkbox-list">{ws.records.devices.map(d => <label key={d.id}><input type="checkbox" name="deviceIds" value={d.id} /><span>{d.data.name}<small>{d.data.code}</small></span></label>)}</div></fieldset></div>{error && <div className="form-error" role="alert">{error}</div>}<div className="modal-footer"><button type="button" className="button secondary" onClick={() => setOpen(false)}>取消</button><button className="button primary" disabled={busy}>{busy ? '正在建立…' : '创建接入凭据'}</button></div></form></Modal>}
    {token && <Modal title="接入凭据已建立" subtitle="密钥只在此处显示一次，请交给对应接入服务保管" onClose={() => setToken('')}><div className="token-result"><KeyRound size={26} /><label>接入密钥<textarea readOnly value={token} rows={3} aria-label="接入密钥" /></label><p>关闭后无法再次查看，可撤销后重新创建。</p></div><div className="modal-footer"><button className="button primary" onClick={() => setToken('')}>已保存，关闭</button></div></Modal>}
    {revoke && <Modal title="撤销接入凭据" subtitle="此服务随后提交的数据将被拒绝，历史记录保留" onClose={() => setRevoke(null)}><div className="modal-footer"><button className="button secondary" onClick={() => setRevoke(null)}>取消</button><button className="button danger" onClick={async () => { try { await api(`/integrations/${revoke}/revoke`, 'POST', {}); setRevoke(null); await load(); await saved('接入凭据已撤销'); } catch (e: any) { setError(e.message); setRevoke(null); } }}>确认撤销</button></div></Modal>}
  </>;
}

function UserPage({ user, saved }: { user: User; saved: (s?: string) => Promise<void> }) {
  const [resetUser,setResetUser]=useState<User|null>(null);
  const [rows, setRows] = useState<(User&{projectAssignments?:{projectId:string;projectName:string;projectRole:string;siteRole:string;reviewEnabled:boolean;expired:boolean}[]})[]>([]); const [open, setOpen] = useState(false); const [editUser, setEditUser] = useState<User | null>(null); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  const load = useCallback(() => api<(User&{projectAssignments?:{projectId:string;projectName:string;projectRole:string;siteRole:string;reviewEnabled:boolean;expired:boolean}[]})[]>('/users').then(setRows).catch(e => setError(e.message)), []); useEffect(() => { void load(); }, [load]);
  const submit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); setBusy(true); setError(''); const fd = new FormData(event.currentTarget); try { if (editUser) await api(`/users/${editUser.id}`, 'PATCH', { active: fd.get('active') === '1', role: fd.get('role') }); else await api('/users', 'POST', Object.fromEntries(fd)); await load(); await saved('账号已保存'); setOpen(false); setEditUser(null); } catch (e: any) { setError(e.message); } finally { setBusy(false); } };
  return <><PageHeading eyebrow="PLATFORM / 访问权限" title="账号权限" description="先设置平台角色，再到工程项目的“项目成员”配置项目岗位；施工员、复核员和资料员在“施工资料”的人员权限中设置。"><button className="button primary" onClick={() => { setOpen(true); setError(''); }}><Plus size={17} />创建账号</button></PageHeading><div className="role-cards">{Object.entries(roleNames).map(([role, label]) => <div key={role}><ShieldCheck size={22} /><h3>{label}</h3><p>{{ admin: '管理基础资料、系统接入、账号与全部业务。', operator: '按项目授权上传施工资料、填报日报及办理工程业务。', viewer: '查看获授权项目的资料与报表，不修改数据。' }[role]}</p></div>)}</div>{error && !open && !editUser && <div className="form-error">{error}</div>}<Panel title="平台成员" meta={`${rows.length} 个账号`}><div className="table-scroll"><table><thead><tr><th>姓名</th><th>账号</th><th>平台角色</th><th>项目岗位 / 施工资料岗位</th><th>状态</th><th>操作</th></tr></thead><tbody>{rows.map(row => <tr key={row.id}><td><strong>{row.name}</strong>{row.id === user.id && <small className="inline-note">当前账号</small>}</td><td>{row.username}</td><td>{roleNames[row.role]}</td><td>{row.role==='admin'?<span>全部项目 · 平台管理员（无需逐项加入）</span>:row.projectAssignments?.length?row.projectAssignments.map(m=><div key={m.projectId}><strong>{m.projectName}</strong><small className="inline-note">{{manager:'项目经理',engineer:'现场成员',finance:'财务成员',viewer:'只读成员'}[m.projectRole]||m.projectRole} · {m.reviewEnabled?m.siteRole:'历史归档流程'}{m.expired?' · 授权未生效或已失效':''}</small></div>):<span>尚未加入项目，请先配置项目成员</span>}</td><td><Badge state={row.active ? 'active' : 'inactive'} /></td><td>{row.id !== user.id && <div className="eng-actions"><button className="text-button" onClick={() => { setEditUser(row); setError(''); }}>调整平台权限</button><button className="text-button" onClick={()=>setResetUser(row)}>重置密码</button></div>}</td></tr>)}</tbody></table></div></Panel>{resetUser&&<ResetPassword key={resetUser.id} target={resetUser} onClose={()=>setResetUser(null)} saved={saved}/>}{(open || editUser) && <Modal title={editUser ? `调整 ${editUser.name} 的平台权限` : '创建平台账号'} onClose={() => { setOpen(false); setEditUser(null); }}><form onSubmit={submit}><div className="form-stack">{!editUser && <><label>姓名<input name="name" required maxLength={60} /></label><label>登录账号<input name="username" required pattern="[a-zA-Z0-9_.\-]{3,40}" autoComplete="off" /></label><label>初始密码<input name="password" type="password" required minLength={6} maxLength={128} autoComplete="new-password" /></label></>}<label>角色<select name="role" defaultValue={editUser?.role || 'operator'}>{Object.entries(roleNames).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select></label>{editUser && <label>账号状态<select name="active" defaultValue={editUser.active ? '1' : '0'}><option value="1">启用</option><option value="0">停用</option></select></label>}</div>{error && <div className="form-error" role="alert">{error}</div>}<div className="modal-footer"><button className="button primary" disabled={busy}>{busy ? '正在保存…' : '保存账号'}</button></div></form></Modal>}</>;
}

function ResetPassword({target,onClose,saved}:{target:User;onClose:()=>void;saved:(message:string)=>Promise<void>}){
 const [busy,setBusy]=useState(false),[error,setError]=useState('');
 async function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();if(busy)return;setError('');const values=new FormData(event.currentTarget);if(values.get('password')!==values.get('confirm')){setError('两次新密码不一致');return;}setBusy(true);try{await api('/users/'+target.id+'/password','POST',{password:values.get('password')});onClose();await saved('已重置 '+target.name+' 的密码，该账号需重新登录。');}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 return <Modal title={'重置 '+target.name+' 的密码'} subtitle={'登录账号：'+target.username+'。已有登录将失效，资料、权限和草稿保留。'} onClose={()=>{if(!busy)onClose();}}><form onSubmit={submit}><div className="form-stack"><label>新密码<input aria-label="新密码" aria-describedby="reset-password-hint" name="password" type="password" required minLength={6} maxLength={128} autoComplete="new-password"/><small id="reset-password-hint">至少6位，不要求复杂字符；无需输入原密码。</small></label><label>确认新密码<input name="confirm" type="password" required minLength={6} maxLength={128} autoComplete="new-password"/></label></div>{error&&<p className="form-error" role="alert">{error}</p>}<div className="modal-footer"><button type="button" className="button" disabled={busy} onClick={onClose}>取消</button><button className="button primary" disabled={busy}>{busy?'正在重置…':'确认重置密码'}</button></div></form></Modal>;
}

function AuditPage({ search }: { search: string }) { const [rows, setRows] = useState<any[]>([]); const [error, setError] = useState(''); const load = useCallback(() => api('/audit').then(setRows).catch(e => setError(e.message)), []); useEffect(() => { void load(); }, [load]); return <><PageHeading eyebrow="PLATFORM / 操作留痕" title="操作审计" description="记录谁在什么时候做了什么，显示最近 200 条操作。"><button className="button secondary" onClick={() => void load()}><RefreshCw size={16} />刷新记录</button></PageHeading>{error && <div className="form-error">{error}</div>}<Panel title="审计记录"><div className="table-scroll"><table><thead><tr><th>操作时间</th><th>操作者</th><th>业务模块</th><th>操作内容</th></tr></thead><tbody>{rows.filter(r => `${r.actor_name}${r.summary}`.includes(search)).map(row => <tr key={row.id}><td className="nowrap">{prettyTime(row.at)}</td><td>{row.actor_name}</td><td>{modules[row.entity]?.name || ({ system: '系统', users: '账号权限', integrations: '服务接入' } as Record<string, string>)[row.entity] || row.entity}</td><td>{row.summary}</td></tr>)}</tbody></table></div>{!rows.length && <Empty title="暂无审计记录" description="账号和业务操作将自动留痕。" />}</Panel></>; }


function Profile({ user, onClose, saved, logout }: { user: User; onClose: () => void; saved: (s?: string) => Promise<void>; logout: () => Promise<void> }) {
  const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  const submit = async (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); setBusy(true); const fd = new FormData(e.currentTarget); try { if (fd.get('password') !== fd.get('confirm')) throw new Error('两次新密码不一致'); await api('/password', 'POST', { current: fd.get('current'), password: fd.get('password') }); await saved('密码已修改，其他会话已失效'); onClose(); } catch (e: any) { setError(e.message); } finally { setBusy(false); } };
  return <Modal title={user.name} subtitle={`${user.username} · ${roleNames[user.role]}`} onClose={onClose}><form onSubmit={submit}><div className="form-stack"><h3>修改密码</h3><label>当前密码<input name="current" type="password" required autoComplete="current-password" /></label><label>新密码<input name="password" type="password" required minLength={6} maxLength={128} autoComplete="new-password" /></label><label>确认新密码<input name="confirm" type="password" required minLength={6} autoComplete="new-password" /></label></div>{error && <div className="form-error" role="alert">{error}</div>}<div className="modal-footer"><button type="button" className="button danger-ghost" disabled={busy} onClick={() => logout().catch(e => setError(e.message))}><LogOut size={16} />退出登录</button><button className="button primary" disabled={busy}>{busy ? '正在修改…' : '修改密码'}</button></div></form></Modal>;
}
